pragma solidity ^0.8.20;

contract TokenVesting {
    struct Schedule {
        uint256 totalAmount;
        uint256 startTime;
        uint256 duration;
        uint256 released;
    }

    mapping(address => Schedule) public schedules;

    function release(address beneficiary) external {
        Schedule storage schedule = schedules[beneficiary];
        require(schedule.totalAmount > 0, "No schedule");

        uint256 vested = (schedule.totalAmount * (block.timestamp - schedule.startTime)) / schedule.duration;
        uint256 unreleased = vested - schedule.released;
        require(unreleased > 0, "Nothing to release");

        schedule.released += unreleased;
        (bool success, ) = beneficiary.call{value: unreleased}("");
        require(success, "Transfer failed");
    }
}

