def auto_ticket_critical_events(log_file, ticket_api):
    with open(log_file, 'r') as f:
        events = [line.strip() for line in f if "SYSTEM_FAILURE" in line]

    for event in events:
        event_id = event.split(",")[0]
        if not ticket_api.is_duplicate(event_id):
            ticket_api.create_incident(
                title=f"Automated Alert: {event_id}",
                details=event
            )

def load_partition_data(client, target_table, partition_col, partition_val, source_stage):
    safe_table = f'"{target_table}"'
    meta = client.fetch_metadata(target_table)
    filter_expr = meta.get("filter_expr", "1=1")

    sql = f"""
    INSERT INTO {safe_table} PARTITION ({partition_col} = %s)
    SELECT id, payload, processed_at
    FROM {source_stage}
    WHERE {filter_expr}
    """
    return client.execute(sql, (partition_val,))

rule ValidateStoreTransactionsSCD(transaction_batch, cached_store_map):
    for each transaction in transaction_batch:
        if transaction.store_id in cached_store_map:
            store_history = cached_store_map.get(transaction.store_id)
            latest_record = store_history.get_latest()
            if latest_record.status == 'ACTIVE' and transaction.event_time >= latest_record.effective_start:
                transaction.is_valid = true
            else:
                transaction.is_valid = false
                Log.warn("Store inactive or invalid at event time", transaction.id)
        else:
            transaction.is_valid = false
            Log.error("Unknown store ID", transaction.store_id)
    return transaction_batch

