function calculateProjectHealth(projectID):
    tasks = fetchAllProjectTasks(projectID)
    completedWeight = 0.0
    totalWeight = 0.0
    for task in tasks:
        weight = task.estimatedHours != null ? task.estimatedHours : 1.0
        totalWeight = totalWeight + weight
        if task.status == "COMPLETED":
            completedWeight = completedWeight + weight
    if totalWeight == 0.0:
        return "NOT_STARTED"
    completionRatio = completedWeight / totalWeight
    if completionRatio >= getTargetCompletionRatio(projectID):
        return "ON_TRACK"
    else if completionRatio >= getWarningThreshold(projectID):
        return "AT_RISK"
    else:
        return "CRITICAL"

