import requests

def check_session_timeout_bypass(target_url, session_token):
    headers = {"Authorization": f"Bearer {session_token}"}
    try:
        res = requests.get(f"{target_url}/api/v1/secure-data", headers=headers, timeout=5)
        if res.status_code != 200:
            return "Session already inactive"

        requests.post(f"{target_url}/api/v1/logout", headers=headers, timeout=5)

        check_res = requests.get(f"{target_url}/api/v1/secure-data", headers=headers, timeout=5)
        data = check_res.json()
        return check_res.status_code == 200 and data.get("authenticated", False)
    except Exception:
        return False

async function processAccountTransfer(db, transfer) {
  const { sourceId, targetId, amount, idempotencyKey } = transfer;
  const existingTx = await db.collection('transfers').doc(idempotencyKey).get();
  if (existingTx.exists) {
    return existingTx.data().result;
  }

  return await db.runTransaction(async (transaction) => {
    const sourceRef = db.collection('accounts').doc(sourceId);
    const targetRef = db.collection('accounts').doc(targetId);
    const sourceDoc = await transaction.get(sourceRef);
    const targetDoc = await transaction.get(targetRef);

    if (!sourceDoc.exists || sourceDoc.data().balance < amount) {
      throw new Error('INSUFFICIENT_FUNDS');
    }

    transaction.update(sourceRef, { balance: sourceDoc.data().balance - amount });
    transaction.update(targetRef, { balance: targetDoc.data().balance + amount });

    return { status: 'SUCCESS', amount };
  });
}

def test_user_session_expiry_validation(auth_service, session_cache):
    expired_users = auth_service.get_expired_session_user_ids()
    assert len(expired_users) > 0, "No expired user sessions returned for test verification"

    for user_id in expired_users:
        session_data = session_cache.get_session(user_id)
        if session_data and session_data.get("is_active"):
            auth_service.force_logout(user_id)

