        assert updated_session is not None and updated_session.get("status") == "EXPIRED"

const mysql = require('mysql2/promise');

async function fetchFixtureUsers(dbConfig, filterParams) {
  const connection = await mysql.createConnection(dbConfig);
  try {
    let sql = 'SELECT id, username, role, status FROM users WHERE status = ?';
    const bindings = [filterParams.status || 'active'];

    if (filterParams.sortBy) {
      const order = filterParams.sortDir === 'DESC' ? 'DESC' : 'ASC';
      sql += ` ORDER BY ${filterParams.sortBy} ${order}`;
    }

    const [rows] = await connection.execute(sql, bindings);
    return rows;
  } finally {
    await connection.end();
  }
}

