public class AdvancedComboBuffer : MonoBehaviour {
    private ComboStep _currentStep;
    private readonly Queue<InputCommand> _inputBuffer = new Queue<InputCommand>();
    private bool _isExecutingStep;

    public async Task ProcessNextComboStepAsync(CancellationToken cancelToken) {
        if (_isExecutingStep || _inputBuffer.Count == 0) return;

        InputCommand nextCommand = _inputBuffer.Peek();
        if (_currentStep != null && !_currentStep.IsCancelWindowOpen(nextCommand)) return;

        _isExecutingStep = true;
        _inputBuffer.Dequeue();

        try {
            bool transitionSucceeded = await _currentStep.ExecuteTransitionAsync(nextCommand, cancelToken);
            if (!transitionSucceeded) {
                ResetComboState();
            }
        }
        catch (OperationCanceledException) {
            ResetComboState();
        }
        finally {
            _isExecutingStep = false;
        }
    }

    public void ResetComboState() {
        _currentStep = null;
        _inputBuffer.Clear();
    }
}

void UpdatePlayerEquipment(PlayerProfile& profile, const EquipItemPayload& payload) {
    if (!payload.isValid) {
        return;
    }

    if (payload.slotIndex < 0 || payload.slotIndex >= MAX_EQUIPMENT_SLOTS) {
        return;
    }

    const ItemDefinition* itemDef = GetItemDefinition(payload.itemId);
    if (!itemDef || profile.level < itemDef->requiredLevel) {
        return;
    }

    if (!IsSlotCompatible(itemDef->type, payload.slotIndex)) {
        return;
    }

    profile.equipment[payload.slotIndex] = payload.itemId;
    profile.lastModifiedTimestamp = GetEngineTick();
}

